import{_ as i,a,a3 as o,o as r}from"./chunks/framework.7XZN1PIK.js";const p=JSON.parse('{"title":"Sasha","description":"","frontmatter":{},"headers":[],"relativePath":"dali/sasha/sasha.md","filePath":"dali/sasha/sasha.md","lastUpdated":1793381922000}'),l={name:"dali/sasha/sasha.md"};function t(c,e,n,d,s,h){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="sasha" tabindex="-1">Sasha <a class="header-anchor" href="#sasha" aria-label="Permalink to &quot;Sasha&quot;">​</a></h1><h2 id="services" tabindex="-1">Services <a class="header-anchor" href="#services" aria-label="Permalink to &quot;Services&quot;">​</a></h2><h3 id="archiver-services" tabindex="-1">Archiver Services <a class="header-anchor" href="#archiver-services" aria-label="Permalink to &quot;Archiver Services&quot;">​</a></h3><h4 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h4><ul><li>The Sasha archiver is responsible for lifecycle management of archived metadata and files for WorkUnits and DFU data.</li><li>It supports both scheduled background archiving and command-driven archive/backup/restore/list flows.</li><li>In bare-metal mode, one combined server runs all archiver roles; in containerized mode, roles are split into dedicated servers.</li></ul><h4 id="main-entry-points" tabindex="-1">Main Entry Points <a class="header-anchor" href="#main-entry-points" aria-label="Permalink to &quot;Main Entry Points&quot;">​</a></h4><ul><li>Server factory declarations: <code>dali/sasha/saarch.hpp</code><ul><li><code>createSashaArchiverServer()</code> (bare-metal combined server)</li><li><code>createSashaWUArchiverServer()</code> (containerized WU archiver)</li><li><code>createSashaDFUWUArchiverServer()</code> (containerized DFU WU archiver)</li><li><code>createSashaDFURecoveryArchiverServer()</code> (containerized DFU recovery archiver)</li><li><code>createSashaCachedWURemoverServer()</code> (containerized cached WU cleanup)</li></ul></li><li>Command dispatcher: <code>processArchiverCommand(ISashaCommand *cmd)</code> in <code>dali/sasha/saarch.cpp</code></li><li>WU listing/query helper used by command actions: <code>WUiterate(ISashaCommand *cmd, const char *mask)</code></li></ul><h4 id="runtime-topology" tabindex="-1">Runtime Topology <a class="header-anchor" href="#runtime-topology" aria-label="Permalink to &quot;Runtime Topology&quot;">​</a></h4><ol><li><p>Bare-metal topology:</p><ul><li><code>CSashaCombinedArchiverServer</code> creates and runs: <ul><li><code>CWorkUnitArchiver</code></li><li><code>CDFUWorkUnitArchiver</code></li><li><code>CDFUrecoveryArchiver</code></li><li><code>CCachedWorkUnitRemover</code></li></ul></li><li>The server loops every minute, checks each archiver schedule, then runs eligible archivers.</li></ul></li><li><p>Containerized topology:</p><ul><li><code>CSashaArchiverServer</code> is a base single-role threaded server.</li><li>Specialized servers each own one archiver instance and one SDS subtree (<code>xpath</code>): <ul><li><code>CSashaWUArchiverServer</code> -&gt; <code>WorkUnits/</code></li><li><code>CSashaDFUWUArchiverServer</code> -&gt; <code>DFU/WorkUnits/</code></li><li><code>CSashaDFURecoveryArchiverServer</code> -&gt; <code>DFU/RECOVERY/job</code></li><li><code>CSashaCachedWURemoverServer</code> -&gt; <code>CachedWorkUnits/</code></li></ul></li></ul></li></ol><h4 id="core-archiver-framework" tabindex="-1">Core Archiver Framework <a class="header-anchor" href="#core-archiver-framework" aria-label="Permalink to &quot;Core Archiver Framework&quot;">​</a></h4><ul><li>Abstract scheduling/scanning logic is centralized in <code>CBranchArchiver</code>.</li><li>Each concrete branch archiver supplies branch-specific behavior via <code>createBranchItem()</code> and item implementation.</li><li><code>CBranchArchiver::action()</code> performs: <ol><li>SDS branch scan (<code>branchxpath</code>)</li><li>Per-item qualification (<code>qualifies()</code>) for archive and optional backup (<code>qualifiesBackup()</code>)</li><li>Sort/prioritization using <code>compare()</code></li><li>Rate/duration control via <code>CSashaSchedule</code></li><li>Archive and backup execution loops</li></ol></li></ul><h4 id="branch-item-contract" tabindex="-1">Branch Item Contract <a class="header-anchor" href="#branch-item-contract" aria-label="Permalink to &quot;Branch Item Contract&quot;">​</a></h4><ul><li><code>IBranchItem</code> defines the per-record decision and execution interface: <ul><li><code>isempty()</code></li><li><code>qualifies()</code></li><li><code>qualifiesBackup()</code></li><li><code>archive()</code></li><li><code>backup()</code></li><li><code>compare(IBranchItem &amp;to)</code></li></ul></li><li>Concrete item implementations: <ul><li><code>CWorkUnitArchiver::cWUBranchItem</code></li><li><code>CDFUWorkUnitArchiver::cDFUWUBranchItem</code></li><li><code>CDFUrecoveryArchiver::cDRBranchItem</code></li></ul></li></ul><h4 id="workunit-archiving-flow" tabindex="-1">WorkUnit Archiving Flow <a class="header-anchor" href="#workunit-archiving-flow" aria-label="Permalink to &quot;WorkUnit Archiving Flow&quot;">​</a></h4><ol><li><p>Scheduler path:</p><ul><li><code>CWorkUnitArchiver</code> scans <code>WorkUnits/*</code>.</li><li>Each WU is wrapped by <code>cWUBranchItem</code>.</li><li><code>qualifies()</code> gates by protection/time/cutoff and state eligibility.</li></ul></li><li><p>Archive execution:</p><ul><li><code>CWorkUnitArchiver::archive()</code> calls <code>doArchiveWorkUnit()</code>.</li><li><code>doArchiveWorkUnit()</code>: <ul><li>Acquires the archive mutex before opening the WU, matching the restore lock order</li><li>Opens WU via <code>IWorkUnitFactory</code></li><li>Optionally version-renames existing LDS files</li><li>Builds an archive metadata snapshot (when publishing is enabled)</li><li>Calls <code>IExtendedWUInterface::archiveWorkUnit()</code></li><li>Publishes the snapshot only after <code>archiveWorkUnit()</code> succeeds; a publish failure is logged and does not undo the archive</li></ul></li></ul></li><li><p>Archive publishing (optional):</p><ul><li>Publisher interface: <code>dali/sasha/wuarchivepublisher.hpp</code></li></ul></li></ol><h4 id="dfu-and-recovery-flows" tabindex="-1">DFU and Recovery Flows <a class="header-anchor" href="#dfu-and-recovery-flows" aria-label="Permalink to &quot;DFU and Recovery Flows&quot;">​</a></h4><ul><li>DFU WorkUnits: <ul><li>Archiver: <code>CDFUWorkUnitArchiver</code></li><li>Archive operation: <code>doArchiveDfuWorkUnit()</code> writes XML to <code>Archive/DFUWorkUnits/...</code></li></ul></li><li>DFU Recovery: <ul><li>Archiver: <code>CDFUrecoveryArchiver</code></li><li>Archive operation writes XML to <code>Archive/DFUrecovery/...</code> and removes original node (when enabled)</li></ul></li><li>Cached WU cleanup: <ul><li><code>CCachedWorkUnitRemover</code> overrides <code>action()</code> to prune older cached entries beyond configured limits.</li></ul></li></ul><h4 id="command-driven-flow" tabindex="-1">Command-Driven Flow <a class="header-anchor" href="#command-driven-flow" aria-label="Permalink to &quot;Command-Driven Flow&quot;">​</a></h4><ul><li><code>processArchiverCommand()</code> handles interactive/remote command actions: <ul><li><code>SCA_ARCHIVE</code>, <code>SCA_BACKUP</code>, <code>SCA_RESTORE</code><ul><li>WU: <code>doArchiveWorkUnit()</code> / <code>doRestoreWorkUnit()</code></li><li>DFU: <code>doArchiveDfuWorkUnit()</code> / <code>doRestoreDfuWorkUnit()</code></li></ul></li><li><code>SCA_LIST</code>, <code>SCA_GET</code>, <code>SCA_WORKUNIT_SERVICES_GET</code>, <code>SCA_LISTDT</code><ul><li>Delegates to <code>WUiterate()</code></li></ul></li></ul></li><li>Results are appended to command IDs for compatibility with existing consumers.</li></ul><h4 id="synchronization-and-error-handling" tabindex="-1">Synchronization and Error Handling <a class="header-anchor" href="#synchronization-and-error-handling" aria-label="Permalink to &quot;Synchronization and Error Handling&quot;">​</a></h4><ul><li>The shared <code>CriticalSection</code> (<code>archivingSect</code>) serializes DFU WorkUnit archive/restore operations within the process and is used for WorkUnit archive/restore synchronization.</li><li>Each server thread catches <code>IException</code>, logs via <code>EXCLOG</code>, and requests server stop on unrecoverable errors.</li><li>WorkUnit archive failures mark SDS metadata (<code>@archiveError</code>, <code>@archiveErrorDate</code>) for retry logic.</li></ul><h4 id="configuration-concepts" tabindex="-1">Configuration Concepts <a class="header-anchor" href="#configuration-concepts" aria-label="Permalink to &quot;Configuration Concepts&quot;">​</a></h4><ul><li>Scheduling/limits are read per archiver branch from config (<code>interval</code>, <code>at</code>, <code>limit</code>, <code>cutoff</code>, optional <code>backup</code>).</li><li>WU archiver-specific options include <code>keepResultFiles</code> and <code>retryinterval</code>.</li><li>Archive publishing is provided by a separate publisher abstraction.</li></ul><h4 id="practical-file-map" tabindex="-1">Practical File Map <a class="header-anchor" href="#practical-file-map" aria-label="Permalink to &quot;Practical File Map&quot;">​</a></h4><ul><li>Archiver interfaces and factories: <code>dali/sasha/saarch.hpp</code></li><li>Main implementation and orchestration: <code>dali/sasha/saarch.cpp</code></li><li>Command model: <code>dali/sasha/sacmd.hpp</code>, <code>dali/sasha/sacmd.cpp</code></li><li>Archive publisher interface: <code>dali/sasha/wuarchivepublisher.hpp</code></li><li>Archive publisher factory: <code>dali/sasha/wuarchivepublisher.cpp</code></li></ul><h3 id="debug-plane-housekeeping-server" tabindex="-1">Debug Plane Housekeeping Server <a class="header-anchor" href="#debug-plane-housekeeping-server" aria-label="Permalink to &quot;Debug Plane Housekeeping Server&quot;">​</a></h3><h4 id="overview-1" tabindex="-1">Overview <a class="header-anchor" href="#overview-1" aria-label="Permalink to &quot;Overview&quot;">​</a></h4><ul><li>This is a maintenance service that automatically manages files and directories on the debug plane using a configured retention period.</li><li>This is required to control the disc space used by post-mortem and other files on the debug plane.</li><li>This service is designed to execute on a schedule; a single log entry for a summary of any deleted (or failed to be deleted) files or deleted directories will be generated.</li></ul><h4 id="installation-and-configuration" tabindex="-1">Installation and Configuration <a class="header-anchor" href="#installation-and-configuration" aria-label="Permalink to &quot;Installation and Configuration&quot;">​</a></h4><ul><li>In containerized mode, the Helm chart deploys the service by default; runtime defaults are shown below. <ul><li><p>For example <code>values.yaml</code> :</p><table tabindex="0"><thead><tr><th style="text-align:left;">attribute</th><th style="text-align:left;">description</th><th style="text-align:left;">default</th><th style="text-align:left;">required</th></tr></thead><tbody><tr><td style="text-align:left;">disabled</td><td style="text-align:left;">When <code>true</code>, Helm omits this service&#39;s deployment.</td><td style="text-align:left;">false</td><td style="text-align:left;">optional</td></tr><tr><td style="text-align:left;">interval</td><td style="text-align:left;">Minimum interval between debug plane housekeeping expiry checking (in hours, 0 disables).</td><td style="text-align:left;">24</td><td style="text-align:left;">optional</td></tr><tr><td style="text-align:left;">at</td><td style="text-align:left;">Optional cron schedule for checking expired files and directories.</td><td style="text-align:left;">Unset; interval only</td><td style="text-align:left;">optional</td></tr><tr><td style="text-align:left;">expiryDays</td><td style="text-align:left;">Default number of days passed that debug plane files or directories are deleted.</td><td style="text-align:left;">14</td><td style="text-align:left;">optional</td></tr></tbody></table></li></ul></li></ul><h4 id="user-guide" tabindex="-1">User Guide <a class="header-anchor" href="#user-guide" aria-label="Permalink to &quot;User Guide&quot;">​</a></h4><h5 id="how-it-works-in-steps" tabindex="-1">How it works in steps <a class="header-anchor" href="#how-it-works-in-steps" aria-label="Permalink to &quot;How it works in steps&quot;">​</a></h5><ol><li>Helm omits the service deployment if <code>disabled</code> is <code>true</code>.</li><li>The service reads <code>expiryDays</code> and <code>interval</code> from its component configuration.</li><li>If either value is 0, the service does not start.</li><li>The debug plane location is read from the component configuration.</li><li>The service <code>Thread</code> is started.</li><li>A loop of the following is started until the service is stopped: <ol><li>A one minute wait is imposed.</li><li>If the schedule using <code>at</code> and <code>interval</code> indicates that the housekeeping is required then: <ol><li>Any exceptions from the following are caught and logged. <ol><li>The debug plane directory list is read.</li><li>The list of files and directories in the debug plane are processed: <ol><li>If the file or directory&#39;s modified date is over <code>expiryDays</code> old then: <ol><li>The file or directory is deleted.</li><li>A counter for each file or directory is maintained.</li></ol></li></ol></li><li>A log entry is made giving the total number of files and directories deleted.</li></ol></li></ol></li></ol></li></ol><h5 id="inputs-and-outputs" tabindex="-1">Inputs and Outputs <a class="header-anchor" href="#inputs-and-outputs" aria-label="Permalink to &quot;Inputs and Outputs&quot;">​</a></h5><ul><li>The component configuration as per <a href="#installation-and-configuration">Installation and Configuration</a> is the input for this service.</li><li>The outputs are any logs generated for errors and deletion statistics.</li></ul><h5 id="error-handling" tabindex="-1">Error Handling <a class="header-anchor" href="#error-handling" aria-label="Permalink to &quot;Error Handling&quot;">​</a></h5><ul><li>Known exceptions are handled to prevent service interruption.</li></ul><h4 id="limitations-and-considerations" tabindex="-1">Limitations and Considerations <a class="header-anchor" href="#limitations-and-considerations" aria-label="Permalink to &quot;Limitations and Considerations&quot;">​</a></h4><ul><li>The service ensures it only runs in containerized environments.</li></ul><h4 id="future-possible-enhancements" tabindex="-1">Future Possible Enhancements <a class="header-anchor" href="#future-possible-enhancements" aria-label="Permalink to &quot;Future Possible Enhancements&quot;">​</a></h4><ul><li>A bare metal implementation.</li><li>Logging freed up disc space statistics.</li></ul>',41)])])}const v=i(l,[["render",t]]);export{p as __pageData,v as default};
